import{z as i,x as m,o as B,c as n,q as t,j as o,D as e,d as A,s,S as l,b as a}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"Rowhammer","description":"","frontmatter":{"title":"Rowhammer","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rowhammer.md","filePath":"cs/rowhammer.md","lastUpdated":1791413859000}'),C={name:"cs/rowhammer.md"};function d(h,E,D,p,R,F){const r=m("Mermaid");return B(),n("div",null,[E[2]||(E[2]=t('<h1 id="rowhammer" tabindex="-1">Rowhammer <a class="header-anchor" href="#rowhammer" aria-label="Permalink to &quot;Rowhammer&quot;">​</a></h1><div class="epigraph"><p>对相邻 DRAM 行的高频激活会在受害行上积累漏电，刷新来不及则位翻转；协议与 ECC 按「随机 FIT」设计时，会被这种定向扰动打穿。</p><footer>—— 据 Kim et al., Flipping Bits in Memory Without Accessing Them, ISCA 2014 整理</footer></div><p><a href="/cs/meltdown-kpti">上一课</a> 仍在 CPU 推测与页表。<a href="/cs/dram-refresh">DRAM 刷新</a> 假定干扰是均匀的。<a href="/cs/mttf-redundancy">MTTF</a> 的 ECC 对付稀疏随机翻转。本课不提供如何对准受害行的程序。缺口是 <strong>Rowhammer：激活干扰作为微结构/器件现象，以及刷新与隔离行等缓解。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DRAM 阵列密，激活一行会在邻行耦合。若某行被反复打开（cache 缺失或显式 flush 使访问到达 DRAM），邻行电荷掉到阈值以下。缺口不是 <a href="/cs/mesi-protocol">MESI</a> 错了<span class="marginnote">直觉类比：相邻两行像共一堵薄墙的房间，攻击者在自家反复开关灯（激活行 A），电磁「震动」隔墙传过去，隔壁桌上快倒的水杯（邻行电荷）被晃得离桌沿越来越近；刷新就是有人按固定节奏把水杯摆回桌子中央——摆的频率不够，杯子就倒了。</span>——内存控制器按合法命令在工作——而是<strong>器件层让「合法高频访问」变成对邻行的写。</strong></p><p><span class="marginnote">Kim 等在 2014 年公开此现象。缓解包括提高刷新率、TRR（追踪行刷新）、隔离行、ECC 升级。没有一种在所有代际上免费且完美。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>微结构视角：LLC 与预取决定哪些行真正打到 DRAM；行缓冲策略影响激活频率。系统：内存控制器检测异常激活模式则对邻行额外刷新。OS：降低敏感页与攻击者页的物理邻接（有限）。本课不描述如何绕过 cache 去锤某一物理行。</p>',8)),(B(),o(l,null,{default:e(()=>[s(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ACT%5B%22%E9%AB%98%E9%A2%91%E6%BF%80%E6%B4%BB%E8%A1%8C%20A%22%5D%20--%3E%20COUP%5B%22%E9%82%BB%E8%A1%8C%E6%BC%8F%E7%94%B5%22%5D%0A%20%20COUP%20--%3E%20REF%5B%22%E5%88%B7%E6%96%B0%E7%AA%97%E5%8F%A3%E5%86%85%E6%9C%AA%E6%81%A2%E5%A4%8D%22%5D%0A%20%20REF%20--%3E%20BIT%5B%22%E5%8F%97%E5%AE%B3%E8%A1%8C%E4%BD%8D%E7%BF%BB%E8%BD%AC%22%5D%0A%20%20MIT%5B%22TRR%20%2F%20%E6%8F%90%E9%AB%98%E5%88%B7%E6%96%B0%20%2F%20ECC%22%5D%20--%3E%20MIT2%5B%22%E9%99%8D%E4%BD%8E%E7%BF%BB%E8%BD%AC%E7%8E%87%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[A("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"与 Spectre：不需要预测器；需要的是物理邻接与激活。ECC 可能把翻转变成可检测错误，三比特以上仍可能漏。这把「正确性」从 ISA 扩展到器件。常见误区：初学者容易以为 Rowhammer 是某个软件 bug、打个补丁就消失——实际上它源于电荷泄漏这种器件物理，任何补丁都只是调参（刷得更勤、隔得更远、纠得更强），现象本身消不掉，只能在翻转率与开销之间选一个工作点。最后一课缓存侧信道回到 SRAM 时序，不依赖 DRAM 翻转。",-1)),E[5]||(E[5]=a("p",null,[A("刷新率加倍直接打带宽与功耗，是粗暴但明确的 MTTF 旋钮。TRR 试图只刷新「被打的邻居」，实现细节各代不同，教学上只需：内存控制器必须把激活历史当成可靠性输入，而不只是时序状态机。"),a("span",{class:"marginnote"},"术语翻译：TRR（Target Row Refresh，定向行刷新）就是用「记下哪些行被高频激活、然后替它们的邻居额外补刷一次」的手段来做「在不拖累全阵列的前提下守住邻行电荷」的事——相当于只给隔壁那只快倒的杯子多摆正几次，而不是全屋杯子加倍摆。")],-1)),E[6]||(E[6]=a("p",null,[a("span",{class:"marginnote"},"数字实例：常规 DRAM 每 64 ms 内要把每一行至少刷一遍。加倍刷新意味着把窗口压到 32 ms、同样次数翻倍——对带宽本就紧张的内存而言，这一项从个位数百分点直接翻上去，而 TRR 只对少数热行补刷，开销小得多。这正是「粗暴旋钮」与「定向旋钮」的差距。")],-1)),(B(),o(l,null,{default:e(()=>[s(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20GOAL%5B%22%E9%97%AE%E9%A2%98%EF%BC%9A%E6%80%8E%E4%B9%88%E9%98%BB%E6%AD%A2%E9%82%BB%E8%A1%8C%E7%94%B5%E8%8D%B7%E8%B7%8C%E7%A0%B4%E9%98%88%E5%80%BC%22%5D%20--%3E%20A%5B%22%E8%B7%AF%E5%BE%84%E4%B8%80%EF%BC%9ATRR%20%E5%AE%9A%E5%90%91%E8%A1%A5%E5%88%B7%22%5D%0A%20%20GOAL%20--%3E%20B%5B%22%E8%B7%AF%E5%BE%84%E4%BA%8C%EF%BC%9A%E5%85%A8%E5%B1%80%E5%88%B7%E6%96%B0%E5%8A%A0%E5%80%8D%22%5D%0A%20%20GOAL%20--%3E%20C%5B%22%E8%B7%AF%E5%BE%84%E4%B8%89%EF%BC%9A%E7%89%A9%E7%90%86%E9%9A%94%E7%A6%BB%E8%A1%8C%22%5D%0A%20%20GOAL%20--%3E%20D%5B%22%E8%B7%AF%E5%BE%84%E5%9B%9B%EF%BC%9AECC%20%E5%85%9C%E5%BA%95%E7%BA%A0%E9%94%99%22%5D%0A%20%20A%20--%3E%20A2%5B%22%E7%A8%8E%EF%BC%9A%E6%8E%A7%E5%88%B6%E5%99%A8%E9%80%BB%E8%BE%91%E4%B8%8E%E5%B0%91%E9%87%8F%E8%A1%A5%E5%88%B7%E5%B8%A6%E5%AE%BD%22%5D%0A%20%20B%20--%3E%20B2%5B%22%E7%A8%8E%EF%BC%9A%E5%85%A8%E9%98%B5%E5%88%97%E5%B8%A6%E5%AE%BD%E4%B8%8E%E5%8A%9F%E8%80%97%E7%BF%BB%E5%80%8D%22%5D%0A%20%20C%20--%3E%20C2%5B%22%E7%A8%8E%EF%BC%9A%E5%9C%B0%E5%9D%80%E6%98%A0%E5%B0%84%E8%87%AA%E7%94%B1%E5%BA%A6%E4%B8%8B%E9%99%8D%22%5D%0A%20%20D%20--%3E%20D2%5B%22%E7%A8%8E%EF%BC%9A%E5%AD%98%E5%82%A8%E4%B8%8E%E7%BC%96%E8%A7%A3%E7%A0%81%E5%BC%80%E9%94%80%EF%BC%8C%E4%B8%94%E5%8F%AA%E4%BF%9D%E5%8D%95%E6%AF%94%E7%89%B9%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不评估具体芯片是否仍可被诱导翻转。也不把云厂商的专有缓解当定理。Prime+Probe 是缓存占用编码，与 Rowhammer 正交：一个读时序，一个写邻居电荷。</p><p>后课默认：DRAM 命令流有物理副作用。SRAM cache 的命中/缺失时序是更经典的侧信道介质。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Rowhammer 是合法激活对邻行的电荷干扰，超出随机 FIT 模型。</li><li>缓解在刷新策略与行追踪，有功耗与带宽税。</li><li>缓存占用时序是下一课 Prime+Probe。</li><li>出处：Kim et al., <em>ISCA</em>, 2014。</li></ul>',5))])}const f=i(C,[["render",d]]);export{T as __pageData,f as default};
